213	/// Deliver ONE attempt, bounded by the authored per-attempt timeout when the
214	/// document declared one (#223).
215	///
216	/// `Err((reason, expired))` carries the failure reason and whether this loop
217	/// ended the attempt on the bound — see [`failure_stand_down`] for why that
218	/// fact travels rather than being re-read out of the reason string.
219	///
220	/// On expiry the dispatch future is DROPPED, which stops this run waiting and
221	/// nothing more. The default `dispatch_async` runs the dispatcher on
222	/// `spawn_blocking`, and a blocking task cannot be cancelled, so the
223	/// worker-side call runs on to its own end and its result is discarded. That
224	/// is the bound this word promises — the same one `with_timeout` gives a
225	/// `wait` — and reaching into the worker's child process is a cancellation
226	/// question, not this one.
227	async fn deliver_one_attempt(
228	    dispatcher: &Arc<dyn ActivityDispatcher>,
229	    delivery: ActivityDispatch,
230	    bound: Option<std::time::Duration>,
231	) -> Result<String, (String, bool)> {
232	    use super::nif_activity_retry::activity_timeout_reason;
233	
234	    let dispatch = Arc::clone(dispatcher).dispatch_async(delivery);
235	    match bound {
236	        None => dispatch.await.map_err(|reason| (reason, false)),
237	        Some(bound) => match tokio::time::timeout(bound, dispatch).await {
238	            Ok(result) => result.map_err(|reason| (reason, false)),
239	            Err(_elapsed) => Err((activity_timeout_reason(bound), true)),
240	        },
241	    }
242	}
