244	/// Drive one activity dispatch to its final outcome under the SDK-declared
245	/// retry policy and per-attempt timeout carried in the dispatch config
246	/// (#197, #223).
247	pub(super) async fn dispatch_with_retries(
248	    dispatcher: &Arc<dyn ActivityDispatcher>,
249	    seam: &RetryRecorderSeam,
250	    request: &ActivityDispatch,
251	) -> RetryLoopOutcome {
252	    use super::nif_activity_retry::{activity_timeout_from_config, retry_policy_from_config};
253	
254	    let policy = retry_policy_from_config(&request.config);
255	    // #223: the AUTHORED per-attempt bound, or `None` for unbounded. The
256	    // engine imposes no deadline of its own — an activity whose document
257	    // declares no `timeout` waits exactly as long as it always has.
258	    let bound = activity_timeout_from_config(&request.config);
259	    let mut attempt = request.attempt;
260	    loop {
261	        let mut delivery = request.clone();
262	        delivery.attempt = attempt;
263	        let (reason, expired) = match deliver_one_attempt(dispatcher, delivery, bound).await {
264	            Ok(payload) => return dispatch_completed(attempt, payload),
265	            Err(failure) => failure,
266	        };
267	        // TRANSPORT-domain worker loss: the activity never executed to a result,
268	        // so it is re-dispatched at the SAME attempt with NOTHING recorded —
269	        // attempt-neutral. The prior behaviour delivered this as a terminal
270	        // failure whenever the activity carried no authored retry policy (the
271	        // SDK's run-exactly-once default), so every infrastructure death read to
272	        // the operator as a red action.
273	        //
274	        // The loop cannot spin: the re-dispatch goes through the same
275	        // unserved-queue park a first dispatch does, so it waits for a worker
276	        // rather than failing fast, and the server stops sending this class once
277	        // its transport-loss budget is spent (a `transport-exhausted:` reason
278	        // that no arm here recognises, so it falls through to the terminal
279	        // below). A terminal recorded elsewhere mid-loop still wins — checked
280	        // before every re-dispatch, because this arm records nothing and would
281	        // otherwise never notice.
282	        if super::nif_activity_retry::is_worker_lost_reason(&reason) {
283	            match worker_loss_stand_down(seam, request, &reason, attempt).await {
284	                Some(terminal) => return RetryLoopOutcome { attempt, terminal },
285	                None => continue,
286	            }
287	        }
288	        if let Some(terminal) = failure_stand_down(policy.as_ref(), &reason, attempt, expired) {
289	            if matches!(terminal, RetryLoopTerminal::Failed(_)) {
290	                record_advisory_exhaustion(seam, request, &reason, attempt).await;
291	            }
292	            return RetryLoopOutcome { attempt, terminal };
293	        }
294	        // The stand-down above returns `Failed` whenever no policy is present,
295	        // so a `None` here is structurally unreachable — kept as the honest
296	        // failure terminal rather than an unwrap.
297	        let Some(policy) = policy.as_ref() else {
298	            return RetryLoopOutcome {
299	                attempt,
300	                terminal: RetryLoopTerminal::Failed(reason),
301	            };
302	        };
303	        // Record the failed attempt durably as a NON-terminal (Retryable)
304	        // `ActivityFailed` — the observable retry record the history cursor
305	        // walks past to the eventual terminal. Recording failures abort the
306	        // loop into an honest terminal failure: an unrecorded retry is a
307	        // silent retry.
308	        match record_retry_event(
309	            seam,
310	            request,
311	            RetryRecord::AttemptFailed {
312	                attempt,
313	                reason: reason.clone(),
314	            },
315	        )
316	        .await
317	        {
318	            RetryRecordOutcome::Recorded => {}
319	            RetryRecordOutcome::Settled => {
320	                return RetryLoopOutcome {
321	                    attempt,
322	                    terminal: RetryLoopTerminal::SettledElsewhere,
323	                };
324	            }
325	            RetryRecordOutcome::EpochClosed => {
326	                return stood_down_on_closed_epoch(request, attempt);
327	            }
328	            RetryRecordOutcome::RecordFailed(record_error) => {
329	                tracing::warn!(
330	                    workflow_id = %request.workflow_id,
331	                    activity_id = %request.activity_id,
332	                    attempt,
333	                    error = %record_error,
334	                    "failed to record a retryable activity failure; failing the activity instead \
335	                     of retrying unrecorded"
336	                );
337	                return RetryLoopOutcome {
338	                    attempt,
339	                    terminal: RetryLoopTerminal::Failed(reason),

340	                };
341	            }
342	        }
343	        announce_and_back_off(policy, request, &reason, attempt).await;
344	        attempt += 1;
345	        // Record the retry delivery's `ActivityStarted` before it goes on the
346	        // wire, so history and the worker wire agree on the attempt (NOI-0) —
347	        // re-guarded, because the backoff sleep is a settle-race window.
348	        match record_retry_event(seam, request, RetryRecord::AttemptStarted { attempt }).await {
349	            RetryRecordOutcome::Recorded => {}
350	            RetryRecordOutcome::Settled => {
351	                return RetryLoopOutcome {
352	                    attempt,
353	                    terminal: RetryLoopTerminal::SettledElsewhere,
354	                };
355	            }
356	            RetryRecordOutcome::EpochClosed => {
357	                return stood_down_on_closed_epoch(request, attempt);
358	            }
359	            RetryRecordOutcome::RecordFailed(record_error) => {
360	                tracing::warn!(
361	                    workflow_id = %request.workflow_id,
362	                    activity_id = %request.activity_id,
363	                    attempt,
364	                    error = %record_error,
365	                    "failed to record a retry attempt start; failing the activity instead of \
366	                     dispatching unrecorded"
367	                );
368	                return RetryLoopOutcome {
369	                    attempt,
370	                    terminal: RetryLoopTerminal::Failed(reason),
371	                };
372	            }
373	        }
374	    }
375	}
