405	/// SAME attempt, recording nothing.
406	///
407	/// The settlement read is load-bearing precisely BECAUSE this path records
408	/// nothing: every other arm of the loop rides `record_retry_event`'s settlement
409	/// check, and without this one a re-dispatch could outlive a `with_timeout`
410	/// expiry (or a workflow terminal) that already decided the ordinal.
411	async fn worker_loss_stand_down(
412	    seam: &RetryRecorderSeam,
413	    request: &ActivityDispatch,
414	    reason: &str,
415	    attempt: u32,
416	) -> Option<RetryLoopTerminal> {
417	    if activity_settled_elsewhere(seam, request).await {
418	        return Some(RetryLoopTerminal::SettledElsewhere);
419	    }
420	    tracing::warn!(
421	        workflow_id = %request.workflow_id,
422	        activity_id = %request.activity_id,
423	        activity_type = %request.name,
424	        attempt,
425	        reason = %reason,
426	        "activity's worker was lost before it reported a result; re-dispatching the same \
427	         attempt (transport loss consumes no authored retry budget)"
428	    );
429	    None
430	}
