432	/// Whether this ordinal (within its run) already carries a recorded terminal.
433	///
434	/// The attempt-neutral worker-loss re-dispatch records NOTHING, so it has no
435	/// `record_retry_event` settle check to ride on; without this read it could
436	/// re-dispatch an ordinal a `with_timeout` expiry (or a workflow terminal)
437	/// already settled. A read failure answers `false` — the loop then re-dispatches
438	/// and the recorder's own guards still refuse a post-terminal append, which is
439	/// strictly safer than standing an activity down on an unreadable history.
440	async fn activity_settled_elsewhere(seam: &RetryRecorderSeam, request: &ActivityDispatch) -> bool {
441	    let recorder = seam.recorder.lock().await;
442	    let Ok(history) = recorder.read_history().await else {
443	        return false;
444	    };
445	    let Ok(history) = crate::durability::current_run_segment(history, &seam.run_id) else {
446	        return false;
447	    };
448	    super::nif_activity_retry::activity_settled(&history, &request.activity_id)
449	}
