183	fn take_runtime_completion(
184	    context: &NifContext,
185	    runtime: &crate::RuntimeHandle,
186	    activity_id: ActivityId,
187	) -> Result<Option<ActivityAwaitStep>, EngineError> {
188	    let ordinal = activity_id.sequence_position();
189	    if let Some((payload, attempt)) = runtime.take_activity_result(context.pid(), ordinal)? {
190	        // NOI-0/#197: the completion task retains the attempt that produced the
191	        // delivered outcome (a retry loop can move it past the first delivery);
192	        // paths that never retry (outbox re-delivery, in-VM) retain nothing and
193	        // resolve to the first delivery exactly as before.
194	        let attempt = attempt.unwrap_or(FIRST_DELIVERY_ATTEMPT);
195	        let recorded_at = chrono::Utc::now();
196	        context
197	            .record_activity_completed(recorded_at, activity_id, payload.clone(), attempt)
198	            .map_err(|error| EngineError::Runtime {
199	                reason: error.error_reason(),
200	            })?;
201	        // Live half of the OBSERVED await seam (see `recorded_resolution_for`):
202	        // the completion is returned to workflow code in this same step and is
203	        // exactly what a replayed await resolves at this position.
204	        context.observe_recorded_at(recorded_at);
205	        return Ok(Some(ActivityAwaitStep::Completed(payload.bytes().to_vec())));
206	    }
207	    if let Some((error, attempt)) = runtime.take_activity_error(context.pid(), ordinal)? {
208	        // #197: an exhausted retry budget fails the workflow with the LAST
209	        // reason verbatim and the final attempt count on the recorded
210	        // terminal `ActivityFailed`.
211	        let attempt = attempt.unwrap_or(FIRST_DELIVERY_ATTEMPT);
212	        let recorded_at = chrono::Utc::now();
213	        context
214	            .record_activity_failed(
215	                recorded_at,
216	                activity_id,
217	                activity_error(error.message.clone()),
218	                attempt,
219	            )
220	            .map_err(|record_error| EngineError::Runtime {
221	                reason: record_error.error_reason(),
222	            })?;
223	        // Live half of the OBSERVED await seam: the terminal failure is
224	        // returned to workflow code in this same step.
225	        context.observe_recorded_at(recorded_at);
226	        return Ok(Some(ActivityAwaitStep::Failed(error.message)));
227	    }
228	    Ok(None)
229	}

